func resolveStorageIdentityByID(ctx context.Context, db *sql.DB, componentID,
    requesterSiteID, requesterDomain string, logger *zap.Logger) (storageIdentity, bool, error) {
    var ident storageIdentity
    found, err := lookupComponentByID(ctx, db, componentID, &ident) // fills FunctionName from the row
    if err != nil || !found {
        return ident, found, err
    }
    ident, err = decideStorageIdentity(ctx, db, ident, requesterSiteID, requesterDomain, logger)
    return ident, true, err
}

// lookupComponentByID: same columns as lookupBaseComponent, keyed on identity
// rather than on a name that does not name a row (25 function values carry more
// than one non-forked row, as of 2026-08-25).
//   SELECT id::text, COALESCE(html_template,''), COALESCE(input_schema::text,'{}'),
//          js_content, function
//   FROM content_components WHERE id = $1::uuid AND forked_from IS NULL

// primary query gains the identity column
//   SELECT id::text, function, input_schema FROM content_components
//   WHERE section_type = $1 AND forked_from IS NULL AND is_active
//     AND component_level = 'section'
//   ORDER BY <ComponentUsageSitesSQL> DESC, updated_at DESC LIMIT 1

ident, ok, err := resolveStorageIdentityByID(ctx, params.DB, rowID, requesterSiteID, requesterDomain, logger)
switch {
case err != nil || !ok:
    // degrade to today's un-pinned advice — never block
    return withVocabulary(advice(function, names, "")), nil
case !ident.IsRegeneration:
    // divert-to-create: no contract exists; advising one is worse than silence
    return withVocabulary(empty), nil
default:
    return withVocabulary(advice(ident.FunctionName,
        schemaFieldNamesSorted([]byte(ident.ExistingSchema)), ident.ExistingID)), nil
}

advisedID, advisedFn := advisedIdentityPin(inputs.GetRaw("advised_identity"))
var ident storageIdentity
if advisedID != "" {
    var found bool
    ident, found, err = resolveStorageIdentityByID(ctx, params.DB, advisedID, requesterSiteID, requesterDomain, logger)
    if err != nil {
        return nil, fmt.Errorf("pinned storage identity resolution failed for %s: %w", advisedID, err)
    }
    if !found {
        LogActionFindings(/* COMPONENT_ADVISED_ROW_VANISHED */)
        ident, err = resolveStorageIdentity(ctx, params.DB, functionName, requesterSiteID, requesterDomain, logger)
    } else if advisedFn != "" && functionName != advisedFn {
        LogActionFindings(/* COMPONENT_FUNCTION_PIN_DIVERGENCE: emitted vs advised */)
    }
} else {
    ident, err = resolveStorageIdentity(ctx, params.DB, functionName, requesterSiteID, requesterDomain, logger) // today, verbatim
}

func TestStoreGeneratedComponent_PinnedRowForeignDependentsStillDivert(t *testing.T) {
    db, mock, _ := sqlmock.New()
    defer db.Close()

    // The pin names the incumbent by id; the census then finds ANOTHER site
    // depending on it, so 311's diversion must still fire.
    mock.ExpectQuery(`FROM content_components\s+WHERE id = \$1::uuid AND forked_from IS NULL`).
        WithArgs(pinnedID).
        WillReturnRows(sqlmock.NewRows([]string{"id", "html_template", "input_schema", "js_content", "function"}).
            AddRow(pinnedID, "<section>x</section>", `{"fields":{"headline":{}}}`, nil, "site-footer"))
    expectForeignDependents(mock, pinnedID, requesterSiteID, foreignSiteID, "other.uk")
    mock.ExpectQuery(`WHERE function = \$1 AND forked_from IS NULL`).
        WithArgs("site-footer-thissite-uk").
        WillReturnError(sql.ErrNoRows)
    mock.ExpectQuery(`INSERT INTO content_components`).
        WillReturnRows(sqlmock.NewRows([]string{"id"}).AddRow(newID))
    // deliberately NO ExpectExec for `UPDATE content_components ... WHERE id = pinnedID`:
    // if the pinned path skips decideStorageIdentity it reaches that statement
    // and sqlmock fails on an expectation that does not exist.

    if _, err := StoreGeneratedComponentAction(ctx, pinnedParams(db, pinnedID, "site-footer")); err != nil {
        t.Fatalf("store: %v", err)
    }
    if err := mock.ExpectationsWereMet(); err != nil {
        t.Fatalf("unmet: %v", err)
    }
}

// RENAMED from TestLoadExistingComponent_SectionTypeHitDoesNotConsultTheResolver.
// That test asserted the DEFECT: a primary hit skipped the dependent census, so
// the advisory could name a row the store would divert away from (bugs_open/311's
// two cases, cured only on the fallback path). Rewritten rather than deleted so a
// reader holding it as evidence finds the correction, not an absence.
func TestLoadExistingComponent_SectionTypeHitRoutesThroughTheIdentityDecision(t *testing.T) {
    db, mock, _ := sqlmock.New()
    defer db.Close()
    expectVocabulary(mock)

    mock.ExpectQuery(`SELECT id::text, function, input_schema`).
        WithArgs("footer").
        WillReturnRows(sqlmock.NewRows([]string{"id", "function", "input_schema"}).
            AddRow(advisoryBaseID, "site-footer", `{"fields":{"headline":{},"links":{}}}`))
    mock.ExpectQuery(`FROM content_components\s+WHERE id = \$1::uuid AND forked_from IS NULL`).
        WithArgs(advisoryBaseID).
        WillReturnRows(sqlmock.NewRows([]string{"id", "html_template", "input_schema", "js_content", "function"}).
            AddRow(advisoryBaseID, "<section>x</section>", `{"fields":{"headline":{},"links":{}}}`, nil, "site-footer"))
    expectNoForeignDependents(mock, advisoryBaseID, advisorySiteID)

    out, err := LoadExistingComponentAction(ctx, advisoryParams(db, "footer", advisorySiteID, "thissite.uk"))
    if err != nil {
        t.Fatalf("advisory must never error: %v", err)
    }
    got := out.(map[string]interface{})
    if got["component_id"] != advisoryBaseID {
        t.Fatalf("pin missing: component_id = %q, want %q", got["component_id"], advisoryBaseID)
    }
    if got["function"] != "site-footer" {
        t.Fatalf("function = %q, want site-footer", got["function"])
    }
    // MUTATION that must turn this red: return advice straight from the primary
    // query without resolveStorageIdentityByID -> the census expectation is unmet.
    if err := mock.ExpectationsWereMet(); err != nil {
        t.Fatalf("unmet: %v", err)
    }
}

-- guard, not a verify SELECT: a non-empty result cannot stop a COMMIT
DO $$
DECLARE hits int;
BEGIN
  SELECT (length(tpl) - length(replace(tpl, anchor, ''))) / length(anchor)
    INTO hits FROM ...;
  IF hits <> 1 THEN
    RAISE EXCEPTION 'anchor drift: expected 1 occurrence, found %', hits;
  END IF;
END $$;
